void show() {
  epaper::init();
  if (!canvas::get().begin()) {
    Serial.println("[屏] 概念图示例：三平面 PSRAM 分配失败");
    return;
  }
  memcpy(canvas::get().plane(canvas::PL_BW), BW, canvas::PLANE_BYTES);
  memcpy(canvas::get().plane(canvas::PL_RED), RED, canvas::PLANE_BYTES);
  memcpy(canvas::get().plane(canvas::PL_YELLOW), YELLOW, canvas::PLANE_BYTES);
  Serial.println("[屏] 概念图 v2 示例帧（模拟器提取三平面），开始上屏...");
  canvas::flush();
}

